python3 - <<'PY'
import re
p = "apps/desktop/src/main/repositoryIntelligence/codewiki/provider.ts"
s = open(p).read()

old_type = '''  type Verification = { present: true; probe: RepositoryIndexProbe } | { present: false; probe: RepositoryIndexProbe; problem: string };'''
new_type = '''  type Verification =
    | {
        present: true;
        probe: RepositoryIndexProbe;
        /**
         * How many files the index holds, as it has just described
         * itself (EO-166).
         *
         * On the present arm alone, because it is read out of the very
         * report that makes this `present` — there is no verification
         * that saw an index and did not learn its size, and no failed
         * one that could invent a number.
         */
        files: number;
      }
    | { present: false; probe: RepositoryIndexProbe; problem: string };'''
assert old_type in s
s = s.replace(old_type, new_type)

old_verify = '''    if (readIndexReport(result.stdout) === null) {
      const problem = `EO could not read CodeWiki's description of the index at ${indexPath}: ${explainOutput(result.stdout, result.stderr)}`;
      return {
        present: false,
        probe: { present: false, indexPath, providerVersion, indexedCommitSha: null, unavailableReason: problem },
        problem,
      };
    }

    return {
      present: true,
      probe: { present: true, indexPath, providerVersion, indexedCommitSha: await headSha(target.workspacePath), unavailableReason: null },
    };'''
new_verify = '''    const report = readIndexReport(result.stdout);
    if (report === null) {
      const problem = `EO could not read CodeWiki's description of the index at ${indexPath}: ${explainOutput(result.stdout, result.stderr)}`;
      return {
        present: false,
        probe: { present: false, indexPath, providerVersion, indexedCommitSha: null, unavailableReason: problem },
        problem,
      };
    }

    return {
      present: true,
      files: report.files,
      probe: { present: true, indexPath, providerVersion, indexedCommitSha: await headSha(target.workspacePath), unavailableReason: null },
    };'''
assert old_verify in s
s = s.replace(old_verify, new_verify)
open(p, "w").write(s)
print("ok")
PY
